window.AUTH=window.AUTH||{};window.AUTH["21-806"]={"d":"21-806","id":"2022/21-806","n":"Health and Hospital Corporation of Marion County v. Talevski","briefs":[{"k":"petitioner","label":"Brief of petitioners Health and Hospital Corporation of Marion County, et al.","date":"2022-07-18","url":"https://www.supremecourt.gov/DocketPDF/21/21-806/230306/20220718175856195_2022-07-18%20Final%20Brief%20HHC%20v.%20Talevski%20PDF-A.pdf","side":"pet","n":133},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2022-07-25","url":"https://www.supremecourt.gov/DocketPDF/21/21-806/230817/20220725195544307_21-806%20-%20US%20Amicus%20Br%20-%20Talevski%20FINAL.pdf","side":"us","n":114},{"k":"respondent","label":"Brief of respondent Ivanka Talevski, Personal Representative of the Estate of Gorgi Talevski, Deceased","date":"2022-09-16","url":"https://www.supremecourt.gov/DocketPDF/21/21-806/238112/20220916160554873_Talevski%20Brief%20and%20App%20-%2021-806.pdf","side":"res","n":127},{"k":"reply","label":"Reply of petitioners Health and Hospital Corporation of Marion County, et al.","date":"2022-10-17","url":"https://www.supremecourt.gov/DocketPDF/21/21-806/243267/20221017144551803_21-806%20Brief.pdf","side":"pet","n":63}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r36_feah.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"0":"passim","3":"21, 22"},"q":[{"src":"brief","b":0,"text":"[t]he express provision of one method of enforcing a substantive rule suggests that Congress intended to preclude others.","cite":"532 U.S. at 290"},{"src":"brief","b":3,"text":"[s]tatutes that focus on the person regulated rather than the individuals protected create ‘no implication of an intent to confer rights on a particular class of persons.’","cite":"532 U.S. 275, 289"},{"src":"brief","b":3,"text":"create no implication of an intent to confer rights on","cite":"532 U.S. at 289"}]},{"t":"case","label":"Allen & Currey Mfg. Co. v. Shreveport Waterworks Co.","cite":"37 So. 980","y":1905,"court":"La.","url":"https://www.courtlistener.com/c/So./37/980/","by":{"0":"19"}},{"t":"case","label":"Anderson v. Ghaly","cite":"930 F.3d 1066","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/930/1066/","by":{"0":"43","2":"39, 40"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"by":{"0":"3, 11, 30","1":"17","2":"12","3":"8, 9, 12"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"Just very briefly. I thought we did drive a wooden stake through Wilder in Gonzaga and Armstrong. It's pretty -- pretty explicit."}]},{"t":"case","label":"Beck v. Kittanning Water Co.","cite":"11 A. 300","y":1887,"court":"Pa.","url":"https://www.courtlistener.com/c/A./11/300/","by":{"0":"19"}},{"t":"case","label":"Blessing v. Freestone","cite":"520 U.S. 329","y":1997,"id":"1996/95-1441","sc":1,"by":{"0":"passim","1":"passim","2":"passim, 21","3":"5, 12, 15, 22"},"q":[{"src":"brief","b":0,"text":"a comprehensive enforcement scheme that is incompatible with individual enforcement under § 1983.","cite":"520 U.S. at 341"},{"src":"brief","b":0,"text":"The State promises to provide certain services to private individuals, in exchange for which the Federal Government promises to give the State funds.","cite":"520 U.S. at 349"},{"src":"brief","b":1,"text":"the provision giving rise to the asserted right [is] couched in mandatory, rather than precatory, terms.","cite":"520 U.S. at 340"},{"src":"brief","b":1,"text":"not so ‘vague and amorphous’ that [their] enforcement would strain judicial competence.","cite":"520 U.S. at 340"},{"src":"brief","b":2,"text":"[A] plaintiff must assert the violation of a federal right, not merely a violation of federal law.","cite":"520 U.S. at 340"},{"src":"brief","b":2,"text":"by creating a comprehensive enforcement scheme that is incompatible with individual enforcement under § 1983,","cite":"520 U.S. at 341"},{"src":"argument","who":"Mr. Robbins","text":"And the command to protect and promote those rights are, as in Blessing, system-wide commands, not an unambiguous assurance of individual entitlement."},{"src":"argument","who":"Mr. Robbins","text":"In the -- that, as in Blessing, the language of the statute, Mr. Chief Justice, is directed to the rights of -- the -- the -- the obligation of the nursing facility to take care of the entire system and not focus on any particular individual."},{"src":"argument","who":"Chief Justice Roberts","text":"And it seems to me that if you're supposed to protect those rights and you're the person who's responsible for conferring -- living up to those rights, that -- that seems to me that it ought to be sufficiently direct under -- under Blessing or Gonzaga or any of the others."}]},{"t":"case","label":"Blymire v. Boistle","cite":"6 Watts 182","y":1837,"court":"Pa.","url":"https://www.courtlistener.com/c/Watts/6/182/","by":{"0":"16"}},{"t":"case","label":"Buckley v. Fitzsimmons","cite":"509 U.S. 259","y":1993,"id":"1992/91-7849","sc":1,"by":{"0":"12"}},{"t":"case","label":"Butterfield v. Hartshorn","cite":"7 N.H. 345","y":1834,"url":"https://www.courtlistener.com/c/N.H./7/345/","by":{"0":"15"}},{"t":"case","label":"Cal. Ass’n of Rural Health Clinics v. Douglas","cite":"738 F.3d 1007","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/738/1007/","by":{"0":"33"}},{"t":"case","label":"Cannon v. Univ. of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"by":{"0":"24","3":"14"},"q":[{"src":"brief","b":0,"text":"the normal play of political forces.","cite":"441 U.S. 677, 743"}]},{"t":"case","label":"Carey v. Piphus","cite":"435 U.S. 247","y":1978,"id":"1977/76-1149","sc":1,"by":{"0":"12"}},{"t":"case","label":"Chamberlain v. New Hampshire Fire Ins. Co.","cite":"55 N.H. 249","y":1875,"url":"https://www.courtlistener.com/c/N.H./55/249/","by":{"0":"15"}},{"t":"case","label":"City of Brooklyn v. Brooklyn City R.R. Co.","cite":"47 N.Y. 475","y":1872,"url":"https://www.courtlistener.com/c/N.Y./47/475/","by":{"0":"20","1":"19, 20","3":"9"}},{"t":"case","label":"City of Rancho Palos Verdes v. Abrams","cite":"544 U.S. 113","y":2005,"id":"2004/03-1601","sc":1,"by":{"0":"41, 42","1":"28","2":"40, 43","3":"15, 17, 23"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"may defeat th[e] presumption by demonstrating that Congress did not intend","cite":"544 U. S., at 120"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"`whether Congress meant [the statute's remedial scheme] to coexist with . . . a § 1983 action'","cite":"544 U. S., at 120"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"[§ 1983] remedy for [these] newly created right[s].","cite":"544 U. S., at 120"},{"src":"argument","who":"Mr. Robbins","text":"First, FNHRA and its implementing regulations provide a comprehensive suite of remedies, including a more restrictive private remedy that forecloses Section 1983 relief under Rancho Palos Verdes."},{"src":"argument","who":"Mr. Robbins","text":"But this Court has twice now taken account of the Sea Clammer and its progeny and twice, once in Rancho Palos Verdes and once in Fitzgerald, has said that the dividing line between what is preclusive and what is not is whether there is a private remedy, not a private judicial remedy, much less a private federal court remedy, a private judicial remedy."},{"src":"argument","who":"Mr. Robbins","text":"I think, if I'm reading the two cases I've just cited correctly, and I think I'm quoting -- citing the -- the language almost verbatim, in fact, I think it uses the phrase \"the dividing line\" if I'm not mistaken in both Fitzgerald and Rancho Palos Verdes."}]},{"t":"case","label":"Conklin v. Smith","cite":"7 Ind. 107","y":1855,"url":"https://www.courtlistener.com/c/Ind./7/107/","by":{"0":"16"}},{"t":"case","label":"Corr. Servs. Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"by":{"0":"27"}},{"t":"case","label":"Cummings v. Premier Rehab Keller, P.L.L.C.","cite":"142 S. Ct. 1562","y":2022,"id":"2021/20-219","sc":1,"by":{"0":"13, 23","1":"17","3":"3"},"q":[{"src":"brief","b":0,"text":"much in the nature of a contract.","cite":"142 S. Ct. 1562, 1568"},{"src":"brief","b":3,"text":"defin[e] the scope of conduct for which funding recipients may be held liable for money damages … with an eye toward ensuring that the receiving entity of federal funds had notice that it will be liable.","cite":"142 S. Ct. 1562, 1570"},{"src":"argument","who":"Mr. Robbins","text":"And at that time, you could not sue on a government-to-government contract unless -- and this is the general state of the law, as Cummings directs us to look at, not little outliers from the regression curve but the main curve that -- that joins most of the cases."},{"src":"argument","who":"Justice Barrett","text":"The question about third-party beneficiaries and the scope of the cause of action I would have thought arose only when we're talking about implied causes of action, like Cummings last term, for example."}]},{"t":"case","label":"DaimlerChrysler v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"by":{"0":"20"}},{"t":"case","label":"Davis v. Clinton Water-Works Co.","cite":"6 N.W. 126","y":1880,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W./6/126/","by":{"0":"19, 20"},"q":[{"src":"brief","b":0,"text":"The city, in exercise of its lawful authority to protect the property of the people, may cause water to be supplied for extinguishing fires, and for other objects demanded by the wants of the people. . . . The people must trust to the municipal government to enforce the discharge of duties and obligations by the officers and agents of that government.","cite":"6 N.W. at 127"}]},{"t":"case","label":"DeCambre v. Brookline Hous. Auth.","cite":"826 F.3d 1","y":2016,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/826/1/","by":{"0":"32"}},{"t":"case","label":"Doremus v. Board of Educ.","cite":"342 U.S. 429","y":1952,"id":"scdb/1951-047","sc":1,"by":{"0":"20"}},{"t":"case","label":"Dow v. Clark","cite":"73 Mass. 198","y":1856,"url":"https://www.courtlistener.com/c/Mass./73/198/","by":{"0":"16"}},{"t":"case","label":"Eaton v. Fairbury Waterworks Co.","cite":"56 N.W. 201","y":1893,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W./56/201/","by":{"0":"19"}},{"t":"case","label":"Egbert v. Boule","cite":"142 S. Ct. 1793","y":2022,"id":"2021/21-147","sc":1,"by":{"0":"24, 27, 29","3":"4"},"q":[{"src":"brief","b":0,"text":"[a]t bottom, creating a cause of action is a legislative endeavor.","cite":"142 S. Ct. at 1802"},{"src":"brief","b":0,"text":"‘the heady days in which this Court assumed common-law powers to create causes of action,’","cite":"142 S. Ct. at 1802"},{"src":"brief","b":3,"text":"[C]reating a cause of action is a legislative endeavor. Courts engaged in that unenviable task must evaluate a range of policy considerations at least as broad as the range a legislature would consider.","cite":"142 S. Ct. 1793, 1802"}]},{"t":"case","label":"Empire State Ins. Co. v. Collins","cite":"54 Ga. 376","y":1875,"url":"https://www.courtlistener.com/c/Ga./54/376/","by":{"0":"16"}},{"t":"case","label":"Ferris v. Carson Water Co.","cite":"16 Nev. 44","y":1881,"url":"https://www.courtlistener.com/c/Nev./16/44/","by":{"0":"19"}},{"t":"case","label":"Fitzgerald v. Barnstable Sch. Comm.","cite":"555 U.S. 246","y":2009,"id":"2008/07-1125","sc":1,"by":{"0":"41","1":"28, 32","2":"39, 40, 41","3":"15, 17, 18"},"q":[{"src":"brief","b":1,"text":"to comply with particular procedures and/or to exhaust particular administrative remedies prior to filing suit.","cite":"555 U.S. 246, 252, 254"},{"src":"brief","b":1,"text":"an administrative procedure resulting in the withdrawal of federal funding","cite":"555 U.S. at 255"},{"src":"brief","b":2,"text":"the crucial consideration is what Congress intended.","cite":"555 U.S. at 252"},{"src":"brief","b":3,"text":"express, private means of redress in the statute itself.","cite":"555 U.S. at 256"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"Congress intended a statute's remedial scheme to `be the exclusive avenue through which a plaintiff may assert [his] claims.'","cite":"555 U. S., at 252"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"Congress intended [that] statute's remedial scheme to `be the exclusive avenue through which a plaintiff may assert [his] claims.'","cite":"555 U. S., at 252"},{"src":"argument","who":"Mr. Robbins","text":"But this Court has twice now taken account of the Sea Clammer and its progeny and twice, once in Rancho Palos Verdes and once in Fitzgerald, has said that the dividing line between what is preclusive and what is not is whether there is a private remedy, not a private judicial remedy, much less a private federal court remedy, a private judicial remedy."},{"src":"argument","who":"Mr. Robbins","text":"But I would -- I -- I -- I would say, Justice Kavanaugh, that the -- you know, I really do insist on the dividing line that this Court has articulated more recently than the -- than the language that you've quoted. It seems to me Fitzgerald --"},{"src":"argument","who":"Mr. Robbins","text":"I think, if I'm reading the two cases I've just cited correctly, and I think I'm quoting -- citing the -- the language almost verbatim, in fact, I think it uses the phrase \"the dividing line\" if I'm not mistaken in both Fitzgerald and Rancho Palos Verdes."}]},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"by":{"0":"28"}},{"t":"case","label":"Fowler v. Athens Water-Works Co.","cite":"9 S.E. 673","y":1889,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./9/673/","by":{"0":"19"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"the quality of the decision’s reasoning; its consistency with related decisions; [and] legal developments since the decision.","cite":"139 S. Ct. 1485, 1499"}]},{"t":"case","label":"Fugure v. Mut. Soc’y of St. Joseph","cite":"46 Vt. 362","y":1874,"url":"https://www.courtlistener.com/c/Vt./46/362/","by":{"0":"16"}},{"t":"case","label":"Gee v. Planned Parenthood of Gulf Coast, Inc.","cite":"139 S. Ct. 408","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./139/408/","sc":1,"by":{"0":"33","3":"3, 4"},"q":[{"src":"brief","b":3,"text":"[n]ot only are the lawsuits themselves a financial burden on the States, but the looming potential for complex litigation inevitably will dissuade state officials from making decisions that they believe to be in the public interest.","cite":"139 S. Ct. 408, 409"}]},{"t":"case","label":"Gonzaga Univ. v. Doe","cite":"536 U.S. 273","y":2002,"id":"2001/01-679","sc":1,"by":{"0":"passim","1":"passim","2":"passim, 21","3":"passim"},"q":[{"src":"brief","b":0,"text":"entails a judicial assumption, with no basis in statutory text, that Congress intended to set itself resolutely against a tradition of deference to state and local [] officials, by subjecting them to private suits for money damages whenever they fail to comply with a federal funding condition.","cite":"536 U.S. at 286 n.5"},{"src":"brief","b":0,"text":"we will not accept respondents’ invitation to have one last drink.","cite":"536 U.S. 273"},{"src":"brief","b":1,"text":"Gonzaga clarified that * * * nothing ‘short of an unambiguously conferred right . . . phrased in terms of the persons benefited’ can support a [S]ection 1983 action.","cite":"536 U.S. at 283"},{"src":"brief","b":1,"text":"showing that Congress specifically foreclosed a remedy under § 1983 . . . expressly, through specific evidence from the statute itself, or impliedly, by creating a comprehensive enforcement scheme that is in[]compatible with individual enforcement under § 1983.","cite":"536 U.S. at 284 n.4"},{"src":"brief","b":3,"text":"only twice [has this Court] found spending legislation to give rise to enforceable rights.","cite":"536 U.S. at 280"},{"src":"brief","b":3,"text":"indication that Congress intend[ed] to create new individual rights,","cite":"536 U.S. at 286"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"`the typical remedy for state noncompliance with federally imposed conditions is not a private cause of action for noncompliance but rather action by the Federal Government to terminate funds to the State.'","cite":"536 U. S., at 280"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"within the general zone of interest that the statute is intended to protect.","cite":"536 U. S., at 283"},{"src":"argument","who":"Chief Justice Roberts","text":"And it seems to me that if you're supposed to protect those rights and you're the person who's responsible for conferring -- living up to those rights, that -- that seems to me that it ought to be sufficiently direct under -- under Blessing or Gonzaga or any of the others."},{"src":"argument","who":"Mr. Robbins","text":"Well -- well, I -- I -- I'm not inclined to think so, though, to be sure, I think our -- the stronger of our two Gonzaga arguments is the middle -- is the Sea Clammers preclusion argument."},{"src":"argument","who":"Mr. Robbins","text":"What I do think, however, is that -- and, again, this is on the assumption now that we're talking about the Gonzaga inquiry. My threshold argument is based on the common law at the time Section 1983 was enacted and on federalism and separation-of-powers principles."}]},{"t":"case","label":"Grammer v. John J. Kane Reg’l Ctrs.Glen Hazel","cite":"570 F.3d 520","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/570/520/","by":{"0":"43, 44"}},{"t":"case","label":"Gunter v. Mooney","cite":"72 Ga. 205","y":1883,"url":"https://www.courtlistener.com/c/Ga./72/205/","by":{"0":"16"}},{"t":"case","label":"H.R. Mock v. Rensselaer Water Co.","cite":"247 N.Y. 160","y":1928,"url":"https://www.courtlistener.com/c/N.Y./247/160/","by":{"0":"22"}},{"t":"case","label":"Hall v. Huntoon","cite":"17 Vt. 244","y":1845,"url":"https://www.courtlistener.com/c/Vt./17/244/","by":{"0":"16"}},{"t":"case","label":"Hernández v. Mesa","cite":"140 S. Ct. 735","y":2020,"id":"2019/17-1678","sc":1,"by":{"0":"24, 29","3":"12"},"q":[{"src":"brief","b":0,"text":"risk[] 6 These separation of powers principles apply both in the Section 1983 context and in the implied right of action context. See Gonzaga, 536 U.S. at 286. As a result, the test for whether the law establishes a right is the same. See ibid. arrogating legislative power,","cite":"140 S. Ct. 735, 742"},{"src":"brief","b":0,"text":"involves balancing interests and often demands compromise.","cite":"140 S. Ct. at 742"}]},{"t":"case","label":"House v. Houston Waterworks Co.","cite":"31 S.W. 179","y":1895,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W./31/179/","by":{"0":"19"}},{"t":"case","label":"Howsmon v. Trenton Water Co.","cite":"24 S.W. 784","y":1893,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W./24/784/","by":{"0":"19"}},{"t":"case","label":"J.I. Case Co. v. Borak","cite":"377 U.S. 426","y":1964,"id":"1963/402","sc":1,"by":{"0":"2, 27"},"q":[{"src":"brief","b":0,"text":"the duty of the courts to be alert to provide such remedies as are necessary to make effective the congressional purpose,","cite":"377 U.S. 426, 433"}]},{"t":"case","label":"Jefferson v. Asch","cite":"55 N.W. 604","y":1893,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./55/604/","by":{"0":"16"}},{"t":"case","label":"Jones v. Thomas","cite":"62 Va. 96","y":1871,"url":"https://www.courtlistener.com/c/Va./62/96/","by":{"0":"16"}},{"t":"case","label":"Kalina v. Fletcher","cite":"522 U.S. 118","y":1997,"id":"1997/96-792","sc":1,"by":{"0":"12","1":"18","2":"27, 28","3":"4"},"q":[{"src":"brief","b":1,"text":"well settled at the time of [Section 1983’s] enactment","cite":"522 U.S. 118, 123"},{"src":"brief","b":2,"text":"construed in the light of common-law principles that were well-settled at the time of its enactment.","cite":"522 U.S. 118, 123"},{"src":"brief","b":3,"text":"Congress intended [§ 1983] to be construed in the light of common-law principles that were well settled at the time of its enactment.","cite":"522 U.S. 118, 123"}]},{"t":"case","label":"Kennedy v. Bremerton Sch. Dist.","cite":"142 S. Ct. 2407","y":2022,"id":"2021/21-418","sc":1,"by":{"0":"34"}},{"t":"case","label":"Kimble v. Mavel Ent., LLC","cite":"576 U.S. 446","y":2015,"url":"https://supreme.justia.com/cases/federal/us/576/446/","sc":1,"by":{"0":"31, 36"},"q":[{"src":"brief","b":0,"text":"doctrinal underpinnings have . . . eroded over time.","cite":"576 U.S. 446, 458"},{"src":"brief","b":0,"text":"Congress can correct any mistake it sees.","cite":"576 U.S. at 456"}]},{"t":"case","label":"Kulwicki v. Munro","cite":"54 N.W. 703","y":1893,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./54/703/","by":{"0":"20"}},{"t":"case","label":"La Mourea v. Rhude","cite":"295 N.W. 304","y":1940,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W./295/304/","by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"would be solely responsible for all physical injuries to persons or property occurring on account of or during the performance of the work under the contract.","cite":"295 N.W. 304, 305"}]},{"t":"case","label":"Lawrence v. Fox","cite":"20 N.Y. 268","y":1859,"url":"https://www.courtlistener.com/c/N.Y./20/268/","by":{"0":"16, 17"}},{"t":"case","label":"Leegin Creative Leather Prods., Inc. v. PSKS, Inc.","cite":"551 U.S. 877","y":2007,"id":"2006/06-480","sc":1,"by":{"0":"36"}},{"t":"case","label":"Maine v. Thiboutot","cite":"448 U.S. 1","y":1980,"id":"1979/79-838","sc":1,"by":{"0":"2","1":"7, 10, 11, 29","2":"1, 8, 9, 21, 23, 24","3":"12"},"q":[{"src":"brief","b":1,"text":"relied on the availability of a § 1983 cause of action.","cite":"448 U.S. at 4"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"civil rights or equal protection laws.","cite":"448 U. S., at 6"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"passed for the express purpose of `enforc[ing] the Provisions of the Fourteenth Amendment.'","cite":"448 U. S., at 25, n. 15"}]},{"t":"case","label":"McCarteney v. Wyoming Nat’l Bank","cite":"1 Wyo. 382","y":1877,"url":"https://www.courtlistener.com/c/Wyo./1/382/","by":{"0":"16"}},{"t":"case","label":"McCready v. White","cite":"417 F.3d 700","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/417/700/","by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"to enlarge the list of implied rights of action.","cite":"417 F.3d 700, 703"}]},{"t":"case","label":"McMahon v. Second Ave. R.R. Co.","cite":"75 N.Y. 231","y":1878,"url":"https://www.courtlistener.com/c/N.Y./75/231/","by":{"0":"20"}},{"t":"case","label":"Mellen v. Whipple","cite":"67 Mass. 317","y":1854,"url":"https://www.courtlistener.com/c/Mass./67/317/","by":{"0":"16"}},{"t":"case","label":"Mendez v. Brown","cite":"311 F. Supp. 2d 134","y":2004,"court":"D. Mass","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/311/134/","by":{"0":"33"}},{"t":"case","label":"Middlesex Cnty. Sewerage Auth. v. Nat'l Sea Clammers Ass'n","cite":"453 U.S. 1","y":1981,"id":"1980/79-1711","sc":1,"by":{"0":"41, 42","1":"28, 34","2":"40, 43","3":"15, 18, 20, 23"},"q":[{"src":"brief","b":0,"text":"the very statute in which this statement was contained.","cite":"453 U.S. at 15"},{"src":"opinion","who":"Justice Barrett, concurring","text":"supplant any remedy that otherwise would be available under § 1983.","cite":"453 U. S. 1, 21"},{"src":"opinion","who":"Justice Barrett, concurring","text":"confe[r] authority to sue . . . on government offcials,","cite":"453 U. S., at 13, 20"},{"src":"opinion","who":"Justice Alito, dissenting","text":"`provides its own comprehensive enforcement scheme, the requirements of that enforcement procedure may not be bypassed by bringing suit directly under § 1983.'","cite":"453 U. S. 1, 20"}]},{"t":"case","label":"Monell v. Dep’t of Soc. Servs.","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"by":{"0":"37","2":"25, 26"},"q":[{"src":"brief","b":0,"text":"[W]e now overrule Monroe v. Pape . . . insofar as it holds that local governments are wholly immune from suit under § 1983.","cite":"436 U.S. 658, 663"}]},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"Congress did not undertake to bring municipal corporations within the ambit","cite":"365 U.S. 167, 187"}]},{"t":"case","label":"N.Y. State Citizens’ Coal. for Children v. Poole","cite":"922 F.3d 69","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/922/69/","by":{"0":"34"}},{"t":"case","label":"Nasello v. Eagleson","cite":"977 F.3d 599","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/977/599/","by":{"0":"32"}},{"t":"case","label":"Nat’l Bank v. Grand Lodge","cite":"98 U.S. 123","y":1878,"id":"scdb/1878-032","sc":1,"by":{"0":"16"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"by":{"0":"3, 25","1":"23"},"q":[{"src":"brief","b":0,"text":"is critical to ensuring that Spending Clause legislation does not undermine the status of the States as independent sovereigns in our federal system.","cite":"567 U.S. 519, 577"},{"src":"opinion","who":"Justice Thomas, dissenting","text":"[m]onetary grants, so-called grants-in-aid, became more frequent during the 1930's, and by 1950 they had reached $20 billion or 11.6% of state and local government expenditures.","cite":"567 U. S. 519, 674"}]},{"t":"case","label":"Nieves v. Bartlett","cite":"139 S. Ct. 1715","y":2019,"id":"2018/17-1174","sc":1,"by":{"0":"12"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"by":{"0":"28"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"by":{"0":"31","2":"25"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"by":{"0":"passim","1":"15, 16, 26","2":"9, 10, 15, 36","3":"2, 11, 13, 20"},"q":[{"src":"brief","b":0,"text":"[T]he States are given the choice of complying with the conditions set forth in the [legislation] or forgoing the benefits of federal funding.","cite":"451 U.S. at 11"},{"src":"brief","b":0,"text":"remedy for state noncompliance with federally imposed conditions is . . . action by the Federal Government to terminate funds to the State.","cite":"451 U.S. at 28"},{"src":"brief","b":1,"text":"much in the nature of a contract.","cite":"451 U.S. 1, 17"},{"src":"brief","b":3,"text":"the legitimacy of Congress’ power to legislate under the spending power thus rests on whether the State voluntarily and knowingly accepts the terms of the ‘contract.’","cite":"451 U.S. 1, 17"},{"src":"brief","b":3,"text":"[i]n expounding a statute, we must not be guided by a single sentence or member of a sentence, but look to the provisions of the whole law, and to its object and policy,","cite":"451 U.S. at 18"},{"src":"opinion","who":"Justice Barrett, concurring","text":"the typical remedy for state noncompliance with federally imposed conditions is not a private cause of action for noncompliance but rather action by the Federal Government to terminate funds to the State.","cite":"451 U. S. 1, 28"},{"src":"argument","who":"Mr. Robbins","text":"Pennhurst, after all, enjoins the Court to look at the whole statute. And when you do that, when you look at the whole statute, the entirety of the FNHRA amendments, what you're going to see is that the core of it, contained in subsections (b), (c), and (d), are a series of commands to the nursing home to regulate and manage its facility in a particular way. (c) refers to the nursing home's ability -- responsibility to protect and promote certain rights."},{"src":"argument","who":"Mr. Robbins","text":"It did in Pennhurst itself with a long section of bill -- called Bill of Rights in Section 6010 of the Rehab Act of '73. That wasn't enough."},{"src":"argument","who":"Mr. Fisher","text":"Precisely because this Court has talked about it in -- in Pennhurst and in other cases that Spending Clause programs are in the nature of a contract."}]},{"t":"case","label":"Perrin v. United States","cite":"444 U.S. 37","y":1979,"id":"1979/78-959","sc":1,"by":{"0":"12"}},{"t":"case","label":"Pharm. Research & Mfrs. of Am. v. Walsh","cite":"538 U.S. 644","y":2003,"id":"2002/01-188","sc":1,"by":{"0":"3, 10"}},{"t":"case","label":"Pierson v. Ray","cite":"386 U.S. 547","y":1967,"id":"1966/79","sc":1,"by":{"0":"12"}},{"t":"case","label":"Pipp v. Reynolds","cite":"20 Mich. 88","y":1870,"url":"https://www.courtlistener.com/c/Mich./20/88/","by":{"0":"16"}},{"t":"case","label":"Planned Parenthood S. Atl. v. Baker","cite":"941 F.3d 687","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/941/687/","by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"Wilder specifically, and the Blessing factors, generally, [are] still good law?","cite":"941 F.3d 687, 709"}]},{"t":"case","label":"Planned Parenthood S. Atl. v. Kerr","cite":"24 F.4th 945","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/24/945/","by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"left hoping that clarity will soon be provided.","cite":"24 F. 4th 945, 959"}]},{"t":"case","label":"Porter v. Richmond & D.R. Co.","cite":"2 S.E. 374","y":1887,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E./2/374/","by":{"0":"20"}},{"t":"case","label":"Rio Grande Cmty. Health Ctr., Inc. v. Rullan","cite":"397 F.3d 56","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/397/56/","by":{"0":"33"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/American Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"by":{"0":"38"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"[I]t frustrates rather than effectuates legislative intent simplistically to assume that whatever furthers the statute’s primary objective must be the law.","cite":"480 U.S. 522, 525-26"}]},{"t":"case","label":"Rogers v. Union Stone Co.","cite":"130 Mass. 581","y":1881,"url":"https://www.courtlistener.com/c/Mass./130/581/","by":{"0":"16"}},{"t":"case","label":"Ross v. Milne","cite":"39 Va. 204","y":1841,"url":"https://www.courtlistener.com/c/Va./39/204/","by":{"0":"15"}},{"t":"case","label":"Schnaier v. Bradley Contracting Co.","cite":"181 A.D. 538","y":1918,"court":"N.Y.","url":"https://www.courtlistener.com/c/A.D./181/538/","by":{"0":"21"},"q":[{"src":"argument","who":"Mr. Robbins","text":"… -- the -- the -- the -- the denominator was gerrymandered to gin up very high numbers, but, if you go back and look at all of the government-to-government contract cases, and I've looked at a fair bit of them, you will find that unless the government contract called out the plaintiff, for example, Schnaier, the Schnaier case from 1918 in New York, or the Little -- the Little case that it cites from 1880, in those cases, they said -- you know, these were the water company and fire company cases of the 19th century -- generally speaking, if your house burned down because the water company didn' …"},{"src":"argument","who":"Mr. Robbins","text":"I -- I -- I respectfully suggest that it is not because, if you look at the cases I've just described, what you will find is that the contract had a -- for example, Schnaier is a -- is a water company case, and it said, in substance, if you don't deliver the water, you will be liable to anyone who is injured."}]},{"t":"case","label":"South Dakota v. Dole","cite":"483 U.S. 203","y":1987,"id":"1986/86-260","sc":1,"by":{"0":"13","3":"2, 3"},"q":[{"src":"brief","b":0,"text":"[I]f Congress desires to condition the States’ receipt of federal funds, it must do so unambiguously.","cite":"483 U.S. 203, 207"},{"src":"brief","b":3,"text":"objectives not thought to be within Article I’s enumerated legislative fields may nevertheless be attained through the use of the spending power and the conditional grant of federal funds.","cite":"483 U.S. 203, 207"}]},{"t":"case","label":"St. Paul Water Co. v. Ware","cite":"83 U.S. 566","y":1872,"id":"scdb/1872-172","sc":1,"by":{"0":"20"},"q":[{"src":"brief","b":0,"text":"keep their streets and highways safe and convenient for travelers.","cite":"83 U.S. 566, 573"}]},{"t":"case","label":"State Oil Co. v. Khan","cite":"522 U.S. 3","y":1997,"id":"1997/96-871","sc":1,"by":{"0":"36"}},{"t":"case","label":"Stuart v. James River & Kanawha Co.","cite":"65 Va. 294","y":1874,"url":"https://www.courtlistener.com/c/Va./65/294/","by":{"0":"16"}},{"t":"case","label":"Styron v. Bell","cite":"53 N.C. 222","y":1860,"url":"https://www.courtlistener.com/c/N.C./53/222/","by":{"0":"16"}},{"t":"case","label":"Suter v. Artist M.","cite":"503 U.S. 347","y":1992,"id":"1991/90-1488","sc":1,"by":{"0":"29","1":"12, 13","2":"passim, 21","3":"12, 13, 22"},"q":[{"src":"brief","b":2,"text":"pains to analyze the statutory provisions in detail, in light of the entire legislative enactment.","cite":"503 U.S. at 357"},{"src":"brief","b":2,"text":"[t]he most important inquiry ... is whether Congress intended to create the private remedy sought by the plaintiffs.","cite":"503 U.S. at 364"},{"src":"argument","who":"Mr. Robbins","text":"The language in the statute that overruled Suter, this Court's Suter decision, made, I thought, painfully clear that it was doing very little."}]},{"t":"case","label":"Talevski ex rel. Talevski v. Health & Hosp. Corp. of Marion Cnty.","cite":"6 F.4th 713","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/713/","by":{"0":"1, 5"}},{"t":"case","label":"Tenney v. Brandhove","cite":"341 U.S. 367","y":1951,"id":"scdb/1950-081","sc":1,"by":{"0":"12"}},{"t":"case","label":"Turner v. McCarty","cite":"22 Mich. 265","y":1871,"url":"https://www.courtlistener.com/c/Mich./22/265/","by":{"0":"16"}},{"t":"case","label":"Vrooman v. Turner","cite":"69 N.Y. 280","y":1877,"url":"https://www.courtlistener.com/c/N.Y./69/280/","by":{"0":"17"}},{"t":"case","label":"Wainwright v. Queens Cnty. Water Co.","cite":"28 N.Y.S. 987","y":1894,"court":"Gen. Term","url":"https://www.courtlistener.com/c/N.Y.S./28/987/","by":{"0":"19"}},{"t":"case","label":"Warren v. Batchelder","cite":"15 N.H. 129","y":1844,"url":"https://www.courtlistener.com/c/N.H./15/129/","by":{"0":"15"}},{"t":"case","label":"Westside Mothers v. Haveman","cite":"133 F. Supp. 2d 549","y":2001,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/133/549/","by":{"0":"17"}},{"t":"case","label":"Wheat v. Rice","cite":"97 N.Y. 296","y":1884,"url":"https://www.courtlistener.com/c/N.Y./97/296/","by":{"0":"17"}},{"t":"case","label":"Wilder v. Virginia Hospital Association","cite":"496 U.S. 498","y":1990,"id":"1989/88-2043","sc":1,"by":{"0":"passim","1":"11, 12","2":"2, 10, 13, 23, 40, 41, 21","3":"12, 13"},"q":[{"src":"brief","b":0,"text":"useful first to consider the history of the reimbursement provision.","cite":"496 U.S. at 505"},{"src":"argument","who":"Mr. Fisher","text":"It has to reject certainly Wilder, which lower courts, including in this case, continue to cite. And I think it needs to set forth a -- a -- a very precise rule that lower courts know that they have to follow, and that would be no implied rights through 1983 and Spending Clause statutes."},{"src":"argument","who":"Chief Justice Roberts","text":"Just very briefly. I thought we did drive a wooden stake through Wilder in Gonzaga and Armstrong. It's pretty -- pretty explicit."},{"src":"argument","who":"Mr. Fisher","text":"But lower courts don't. They cite Wilder all the time, and especially in the context of Medicaid litigation, we can't get around Wilder. That is the case --"}]},{"t":"case","label":"Will v. Michigan Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"by":{"0":"12, 18, 26","1":"32","3":"4, 5, 11"},"q":[{"src":"brief","b":0,"text":"that members of the 42d Congress were familiar with common-law principles, . . . and that they likely intended these common-law principles to obtain, absent specific provisions to the contrary.","cite":"491 U.S. 58, 67"},{"src":"brief","b":0,"text":"Congress intends to alter the ‘usual constitutional balance between the States and the Federal Government,’ it must make its intention to do so ‘unmistakably clear in the language of the statute.’","cite":"491 U.S. at 65"}]},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"by":{"0":"11"},"q":[{"src":"brief","b":0,"text":"consistent with [its] ‘ordinary meaning . . . at the time Congress enacted the statute.’","cite":"138 S. Ct. 2067, 2070"}]},{"t":"case","label":"Wright v. City of Roanoke Redevelopment & Housing Authority","cite":"479 U.S. 418","y":1987,"id":"1986/85-5915","sc":1,"by":{"0":"2","1":"12, 29","2":"10, 13, 23, 40, 41","3":"12"},"q":[{"src":"brief","b":1,"text":"the existence of a state administrative remedy does not ordinarily foreclose resort to § 1983.","cite":"479 U.S. at 427"},{"src":"brief","b":2,"text":"the existence of a state administrative remedy does not ordinarily foreclose resort to § 1983,","cite":"479 U.S. at 427"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 1396a","url":"https://www.law.cornell.edu/uscode/text/42/1396a","subs":["(a)(17)","(a)(13)(A)","(a)","(a)(5)","(a)(8)","(a)(10)(A)","(a)(23)","(b)"],"by":{"0":"33, 27","1":"2, 2, 21, 2, 21, 22, 2"},"q":[{"src":"brief","b":1,"text":"a single State agency to administer or to supervise the administration of the plan.","cite":"42 U.S.C. 1396a(a)(5)"}]},{"t":"usc","label":"42 U.S.C. § 1396r","url":"https://www.law.cornell.edu/uscode/text/42/1396r","subs":["(c)","(c)(1)(A)(ii)","(c)(1)(A)(vi)","(c)(2)(A)","(c)(2)(A)(i)","(c)(2)(A)(ii)","(c)(2)(A)(iii)","(e)(3)","(g)(2)(A)","(h)(2)(A)(i)","(h)(2)(A)(ii)","(h)(2)(A)(iii)","(h)(2)(A)(iv)","(h)(3)(A)","(h)(3)(B)","(h)(3)(C)","(h)(8)","(c)(1)(A)","(c)(1)(A)(ii)(I)","(c)(2)","(c)(2)(F)","(e)(7)","(g)(1)(A)","(g)(2)","(g)(2)(A)(ii)(III)","(g)(2)(B)","(g)(3)","(g)(4)","(g)(4)(A)","(g)(5)","(h)","(c)(1)(A)(iv)","(c)(1)(B)","(c)(1)(B)(i)","(c)(1)(B)(ii)","(c)(1)(C)","(b)","(d)","(e)","(f)","(g)"],"stext":{"head":"§1396r. Requirements for nursing facilities","paras":[[0,"(a) \"Nursing facility\" defined"],[0,"In this subchapter, the term \"nursing facility\" means an institution (or a distinct part of an institution) which—"],[1,"(1) is primarily engaged in providing to residents—"],[2,"(A) skilled nursing care and related services for residents who require medical or nursing care,"],[2,"(B) rehabilitation services for the rehabilitation of injured, disabled, or sick persons, or"],[2,"(C) on a regular basis, health-related care and services to individuals who because of their mental or physical condition require care and services (above the level of room and board) which can be made available to them only through institutional facilities,"],[1,"and is not primarily for the care and treatment of mental diseases;"],[1,"(2) has in effect a transfer agreement (meeting the requirements of section 1395x(l) of this title) with one or more hospitals having agreements in effect under section 1395cc of this title; and"],[1,"(3) meets the requirements for a nursing facility described in subsections (b), (c), and (d) of this section."],[0,"Such term also includes any facility which is located in a State on an Indian reservation and is certified by the Secretary as meeting the requirements of paragraph (1) and subsections (b), (c), and (d)."],[0,"(b) Requirements relating to provision of services"],[0,"(1) Quality of life"],[0,"(A) In general"],[2,"A nursing facility must care for its residents in such a manner and in such an environment as will promote maintenance or enhancement of the quality of life of each resident."],[0,"(B) Quality assessment and assurance"],[2,"A nursing facility must maintain a quality assessment and assurance committee, consisting of the director of nursing services, a physician designated by the facility, and at least 3 other members of the facility's staff, which (i) meets at least quarterly to identify issues with respect to which quality assessment and assurance activities are necessary and (ii) develops and implements appropriate plans of action to correct identified quality deficiencies. A State or the Secretary may not require disclosure of the records of such committee except insofar as such disclosure is related to the compliance of such committee with the requirements of this subparagraph."],[0,"(2) Scope of services and activities under plan of care"],[1,"A nursing facility must provide services and activities to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident in accordance with a written plan of care which—"],[2,"(A) describes the medical, nursing, and psychosocial needs of the resident and how such needs will be met;"],[2,"(B) is initially prepared, with the participation to the extent practicable of the resident or the resident's family or legal representative, by a team which includes the resident's attending physician and a registered professional nurse with responsibility for the resident; and"],[2,"(C) is periodically reviewed and revised by such team after each assessment under paragraph (3)."],[0,"(3) Residents' assessment"],[0,"(A) Requirement"],[2,"A nursing facility must conduct a comprehensive, accurate, standardized, reproducible assessment of each resident's functional capacity, which assessment—"],[3,"(i) describes the resident's capability to perform daily life functions and significant impairments in functional capacity;"],[3,"(ii) is based on a uniform minimum data set specified by the Secretary under subsection (f)(6)(A);"],[3,"(iii) uses an instrument which is specified by the State under subsection (e)(5); and"],[3,"(iv) includes the identification of medical problems."],[0,"(B) Certification"],[0,"(i) In general"],[3,"Each such assessment must be conducted or coordinated (with the appropriate participation of health professionals) by a registered professional nurse who signs and certifies the completion of the assessment. Each individual who completes a portion of such an assessment shall sign and certify as to the accuracy of that portion of the assessment."],[0,"(ii) Penalty for falsification"],[3,"(I) An individual who willfully and knowingly certifies under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $1,000 with respect to each assessment."],[3,"(II) An individual who willfully and knowingly causes another individual to certify under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $5,000 with respect to each assessment."],[3,"(III) The provisions of section 1320a–7a of this title (other than subsections (a) and (b)) shall apply to a civil money penalty under this clause in the same manner as such provisions apply to a penalty or proceeding under section 1320a–7a(a) of this title."],[0,"(iii) Use of independent assessors"],[3,"If a State determines, under a survey under subsection (g) or otherwise, that there has been a knowing and willful certification of false assessments under this paragraph, the State may require (for a period specified by the State) that resident assessments under this paragraph be conducted and certified by individuals who are independent of the facility and who are approved by the State."],[0,"(C) Frequency"],[0,"(i) In general"],[3,"Such an assessment must be conducted—"],[4,"(I) promptly upon (but no later than 14 days after the date of) admission for each individual admitted on or after October 1, 1990, and by not later than October 1, 1991, for each resident of the facility on that date;"],[4,"(II) promptly after a significant change in the resident's physical or mental condition; and"],[4,"(III) in no case less often than once every 12 months."],[0,"(ii) Resident review"],[3,"The nursing facility must examine each resident no less frequently than once every 3 months and, as appropriate, revise the resident's assessment to assure the continuing accuracy of the assessment."],[0,"(D) Use"],[2,"The results of such an assessment shall be used in developing, reviewing, and revising the resident's plan of care under paragraph (2)."],[0,"(E) Coordination"],[2,"Such assessments shall be coordinated with any State-required preadmission screening program to the maximum extent practicable in order to avoid duplicative testing and effort. In addition, a nursing facility shall notify the State mental health authority or State mental retardation or developmental disability authority, as applicable, promptly after a significant change in the physical or mental condition of a resident who is mentally ill or mentally retarded."],[0,"(F) Requirements relating to preadmission screening for mentally ill and mentally retarded individuals"],[2,"Except as provided in clauses (ii) and (iii) of subsection (e)(7)(A), a nursing facility must not admit, on or after January 1, 1989, any new resident who—"],[3,"(i) is mentally ill (as defined in subsection (e)(7)(G)(i)) unless the State mental health authority has determined (based on an independent physical and mental evaluation performed by a person or entity other than the State mental health authority) prior to admission that, because of the physical and mental condition of the individual, the individual requires the level of services provided by a nursing facility, and, if the individual requires such level of services, whether the individual requires specialized services for mental illness, or"],[3,"(ii) is mentally retarded (as defined in subsection (e)(7)(G)(ii)) unless the State mental retardation or developmental disability authority has determined prior to admission that, because of the physical and mental condition of the individual, the individual requires the level of services provided by a nursing facility, and, if the individual requires such level of services, whether the individual requires specialized services for mental retardation."],[2,"A State mental health authority and a State mental retardation or developmental disability authority may not delegate (by subcontract or otherwise) their responsibilities under this subparagraph to a nursing facility (or to an entity that has a direct or indirect affiliation or relationship with such a facility)."],[0,"(4) Provision of services and activities"],[0,"(A) In general"],[2,"To the extent needed to fulfill all plans of care described in paragraph (2), a nursing facility must provide (or arrange for the provision of)—"],[3,"(i) nursing and related services and specialized rehabilitative services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(ii) medically-related social services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(iii) pharmaceutical services (including procedures that assure the accurate acquiring, receiving, dispensing, and administering of all drugs and biologicals) to meet the needs of each resident;"],[3,"(iv) dietary services that assure that the meals meet the daily nutritional and special dietary needs of each resident;"],[3,"(v) an on-going program, directed by a qualified professional, of activities designed to meet the interests and the physical, mental, and psychosocial well-being of each resident;"],[3,"(vi) routine dental services (to the extent covered under the State plan) and emergency dental services to meet the needs of each resident; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396r?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 5, 5, 43, 45, 6, 40, 5, 43, 46, 46, 46, 6, 39, 41, 5, 41, 5, 41, 5, 41, 5, 41, 6, 41, 6, 41, 6, 41, 42","1":"3, 3, 25, 26, 27, 3, 30, 25, 3, 26, 27, 23, 4, 31, 34, 4, 32, 4, 4, 4, 4, 4, 30, 4, 5, 31, 5, 5, 33, 5, 5, 4, 34","2":"13, 33, 13, 33, 14, 39, 14, 33, 33, 14, 33, 14, 33, 39, 42, 16, 37, 40, 43","3":"19, 21, 16, 19, 21, 16, 19, 21, 22, 22, 16, 19, 21, 21, 21, 21, 16, 22"},"q":[{"src":"brief","b":0,"text":"nursing facility must protect and promote . . . [t]he right to be free from . . . physical or chemical restraints","cite":"42 U.S.C. § 1396r(c)(1)(A)(ii)"},{"src":"brief","b":0,"text":"provide for a fair mechanism . . . for hearing appeals on transfers and discharges of residents of such facilities.","cite":"42 U.S.C. § 1396r(e)(3)"},{"src":"brief","b":1,"text":"payment for the costs of relocation of residents to other facilities, maintenance of operation of a facility pending correction of deficiencies or closure, and reimbursement of residents for personal funds lost.","cite":"42 U.S.C. 1396r(h)(2)(A)(ii)"},{"src":"brief","b":2,"text":"[t]he remedies provided under this subsection are in addition to those otherwise available under State or Federal law and shall not be construed as limiting such other remedies, including any remedy available to an individual at common law.","cite":"42 U.S.C. § 1396r(h)(8)"},{"src":"brief","b":2,"text":"are in addition to those otherwise available under","cite":"42 U.S.C. § 1396r(h)(8)"},{"src":"brief","b":3,"text":"The remedies provided under this subsection are in addition to those otherwise available under State or Federal law.","cite":"42 U.S.C. § 1396r(h)(8)"},{"src":"opinion","who":"Justice Alito, dissenting","text":"nursing facility must protect and promote the rights of each resident, including . . . [t]he right to be free from . . . chemical restraints imposed for purposes of discipline or convenience and not required to treat the resident's medical symptoms.","cite":"42 U. S. C. § 1396r(c)(1)(A)"}]},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"passim","2":"passim, 24","3":"passim"},"q":[{"src":"brief","b":1,"text":"rights * * * secured by the Constitution and laws","cite":"42 U.S.C. 1983"},{"src":"brief","b":1,"text":"to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress.","cite":"42 U.S.C. 1983"},{"src":"brief","b":2,"text":"any rights, privileges, or immunities secured by the Constitution and laws.","cite":"42 U.S.C. § 1983"},{"src":"brief","b":2,"text":"food stamps and other welfare benefits.","cite":"42 U.S.C. 1983"},{"src":"opinion","who":"Justice Gorsuch, concurring","text":"rights . . . secured by . . . la[w].","cite":"42 U. S. C. § 1983"},{"src":"argument","who":"Mr. Robbins","text":"Chief Justice, and may it please the Court: The key to Spending Clause statutes, this Court said in Arlington Central School District, \"is what the states are clearly told regarding the conditions that go along with the acceptance of federal funds.\" Among the most costly conditions that may go along with the acceptance of federal funds is exposure to private litigation under Section 1983."},{"src":"argument","who":"Mr. Robbins","text":"My threshold argument is based on the common law at the time Section 1983 was enacted and on federalism and separation-of-powers principles."},{"src":"argument","who":"Justice Jackson","text":"Okay. Then it seems to me odd to suggest that we as a Court can reinterpret the word \"law\" in Section 1983 to carve anything out."}]},{"t":"usc","label":"20 U.S.C. § 1415","url":"https://www.law.cornell.edu/uscode/text/20/1415","subs":["(i)(3)(A)"],"by":{"0":"25"}},{"t":"usc","label":"29 U.S.C. § 794a","url":"https://www.law.cornell.edu/uscode/text/29/794a","subs":["(a)"],"by":{"0":"25"}},{"t":"reg","label":"42 C.F.R. § 431.220","url":"https://www.ecfr.gov/current/title-42/section-431.220","subs":["(a)(2)"],"by":{"0":"40"}},{"t":"reg","label":"42 C.F.R. § 431.240","url":"https://www.ecfr.gov/current/title-42/section-431.240","subs":["(a)(3)","(b)"],"by":{"0":"40, 40"}},{"t":"reg","label":"42 C.F.R. § 431.241","url":"https://www.ecfr.gov/current/title-42/section-431.241","subs":["(b)"],"by":{"0":"40"}},{"t":"reg","label":"42 C.F.R. § 431.242","url":"https://www.ecfr.gov/current/title-42/section-431.242","subs":["(a)","(b)","(e)"],"by":{"0":"40, 40, 40"}},{"t":"reg","label":"42 C.F.R. § 483.10","url":"https://www.ecfr.gov/current/title-42/section-483.10","subs":["(j)(1)","(j)(4)(i)","(j)(4)(v)","(j)(4)(vi)"],"by":{"0":"40, 40","3":"16, 17"},"q":[{"src":"brief","b":0,"text":"with respect to care and treatment which has been furnished","cite":"42 C.F.R. § 483.10(j)(1)"},{"src":"brief","b":3,"text":"the date the grievance was received, a summary statement of the resident’s grievance, the steps taken to investigate the grievance, a summary of the pertinent findings or conclusions regarding the resident’s concern(s), a statement as to whether the grievance was confirmed or not confirmed, any corrective action taken or to be taken by the facility as a result of the grievance, and the date the written decision was issued.","cite":"42 C.F.R. § 483.10(j)(4)(v)"}]},{"t":"case","label":"M.H. Hoeflich and E. Perelmuter, The Anatomy of a Leading Case: Lawrence v. Fox in the Courts, the Casebooks, and the Commentaries","cite":"21 U. Mich. J.L. Reform 721","y":1988,"url":"https://www.courtlistener.com/c/U.%20Mich.%20J.L.%20Reform/21/721/","by":{"0":"17"}},{"t":"case","label":"Biden v. Missouri","cite":"142 S. Ct. 647","y":2022,"id":"2021/21a240","sc":1,"by":{"1":"2, 3"}},{"t":"case","label":"Bryson v. Shumway","cite":"308 F.3d 79","y":2002,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/308/79/","by":{"1":"22"}},{"t":"case","label":"(III) Cases—Continued: Carter v. Stanton","cite":"405 U.S. 669","y":1972,"id":"1971/70-5082","sc":1,"by":{"1":"11"}},{"t":"case","label":"Coventry Health Care of Missouri, Inc. v. Nevils","cite":"137 S. Ct. 1190","y":2017,"id":"2016/16-149","sc":1,"by":{"1":"17"}},{"t":"case","label":"Doe v. Chiles","cite":"136 F.3d 709","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/136/709/","by":{"1":"22"}},{"t":"case","label":"Doe v. Kidd","cite":"501 F.3d 348","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/501/348/","by":{"1":"21"}},{"t":"case","label":"Does v. Gillespie","cite":"867 F.3d 1034","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1034/","by":{"1":"22"},"q":[{"src":"argument","who":"Justice Kavanaugh","text":"So the -- the -- the issue here, I think, that if we get to this issue we'd have to nail down, is exactly under what circumstances the private administrative remedy in the statute precludes 1983. Does that sound like the question?"},{"src":"argument","who":"Justice Thomas","text":"Then the next step would be: Does it also give a right to a third-party beneficiary to vindicate some of those rights? That's the way we have done it."}]},{"t":"case","label":"Edelman v. Jordan","cite":"415 U.S. 651","y":1974,"id":"1973/72-1410","sc":1,"by":{"1":"11, 21","2":"1, 6, 23","3":"11"},"q":[{"src":"brief","b":1,"text":"Rosado v. Wyman, 397 U.S. 397 (1970), held that suits in federal court under § 1983 are proper to secure compliance with the provisions of the Social Security Act on the part of participating States.","cite":"415 U.S. 651, 675"},{"src":"brief","b":1,"text":"h[o]ld[ing] that suits in federal court under § 1983 are proper to secure compliance with the provisions of the Social Security Act.","cite":"415 U.S. at 675"}]},{"t":"case","label":"Fairholme Funds, Inc. v. United States","cite":"26 F.4th 1274","y":2022,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.4th/26/1274/","by":{"1":"20"}},{"t":"case","label":"Hagans v. Lavine","cite":"415 U.S. 528","y":1974,"id":"1973/72-6476","sc":1,"by":{"1":"11","2":"6"}},{"t":"case","label":"Harris v. McRae","cite":"448 U.S. 297","y":1980,"id":"1979/79-1268","sc":1,"by":{"1":"17"}},{"t":"case","label":"Harris v. Olszewski","cite":"442 F.3d 456","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/442/456/","by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"uses the kind of ‘individually focused terminology’ that ‘unambiguously confer[s]’ an ‘individual entitlement’ under the law.","cite":"442 F.3d 456, 461"}]},{"t":"case","label":"Hendrick v. Lindsay","cite":"93 U.S. 143","y":1876,"id":"scdb/1876-033","sc":1,"by":{"1":"19","2":"28","3":"8"},"q":[{"src":"brief","b":1,"text":"the right of a party to maintain assumpsit on a promise not under seal, made to another for his benefit, although much controverted, is now the prevailing rule in this country.","cite":"93 U.S. 143, 149"}]},{"t":"case","label":"Kimble v. Marvel Entertainment, LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"by":{"1":"21, 24","2":"25"},"q":[{"src":"brief","b":1,"text":"effectively become part of the statutory scheme","cite":"576 U.S. at 456"}]},{"t":"case","label":"King v. Smith","cite":"392 U.S. 309","y":1968,"id":"1967/949","sc":1,"by":{"1":"11","2":"5"}},{"t":"case","label":"Lawrence County v. Lead-Deadwood School District","cite":"469 U.S. 256","y":1985,"id":"1984/83-240","sc":1,"by":{"1":"17"}},{"t":"case","label":"Maine Community Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"by":{"1":"10"},"q":[{"src":"brief","b":1,"text":"[S]tatutory interpretation ‘begins with the text.’","cite":"140 S. Ct. 1308, 1320"}]},{"t":"case","label":"Miller v. Youakim","cite":"440 U.S. 125","y":1979,"id":"1978/77-742","sc":1,"by":{"1":"11, 29","2":"6, 23"}},{"t":"case","label":"O’Bannon v. Town Court Nursing Center","cite":"447 U.S. 773","y":1980,"id":"1979/78-1318","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"gives recipients the right to choose among a range of qualified providers, without government interference,","cite":"447 U.S. 773, 785"}]},{"t":"case","label":"Planned Parenthood South Atlantic v. Kerr","cite":"27 F.4th 945","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/27/945/","by":{"1":"22"}},{"t":"case","label":"Quern v. Mandley","cite":"436 U.S. 725","y":1978,"id":"1977/76-1159","sc":1,"by":{"1":"11","2":"6"}},{"t":"case","label":"Robinson v. Chamberlain","cite":"34 N.Y. 389","y":1866,"url":"https://www.courtlistener.com/c/N.Y./34/389/","by":{"1":"20","3":"9"}},{"t":"case","label":"Romano v. Greenstein","cite":"721 F.3d 373","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/721/373/","by":{"1":"21"}},{"t":"case","label":"S.D. ex rel. Dickson v. Hood","cite":"391 F.3d 581","y":2004,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/391/581/","by":{"1":"22"}},{"t":"case","label":"Sabree v. Richman","cite":"367 F.3d 180","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/367/180/","by":{"1":"22"}},{"t":"case","label":"Smith v. Robinson","cite":"468 U.S. 992","y":1984,"id":"1983/82-2120","sc":1,"by":{"1":"28","3":"15, 17"},"q":[{"src":"opinion","who":"Justice Alito, dissenting","text":"[a]llowing a plaintiff to circumvent [FNHRA's] administrative remedies would be inconsistent with Congress' carefully tailored scheme.","cite":"468 U. S. 992, 1012"}]},{"t":"case","label":"Steward Machine Co. v. Davis","cite":"301 U.S. 548","y":1937,"id":"1900-1940/301us548","sc":1,"by":{"1":"16","2":"30"}},{"t":"case","label":"Townsend v. Swank","cite":"404 U.S. 282","y":1971,"id":"1971/70-5021","sc":1,"by":{"1":"11","2":"5, 6, 23"}},{"t":"case","label":"Van Lare v. Hurley","cite":"421 U.S. 338","y":1975,"id":"1974/74-453","sc":1,"by":{"1":"11","2":"6, 23"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","by":{"1":"34"}},{"t":"usc","label":"42 U.S.C. § 1997","url":"https://www.law.cornell.edu/uscode/text/42/1997","subs":["(1)(A)","(1)(B)(v)","(2)"],"by":{"1":"34","2":"6, 7, 7, 7"}},{"t":"usc","label":"42 U.S.C. § 15001","url":"https://www.law.cornell.edu/uscode/text/42/15001","by":{"1":"34"}},{"t":"usc","label":"42 U.S.C. § 1320a-2","url":"https://www.law.cornell.edu/uscode/text/42/1320a-2","stext":{"head":"§1320a–2. Effect of failure to carry out State plan","paras":[[0,"In an action brought to enforce a provision of this chapter, such provision is not to be deemed unenforceable because of its inclusion in a section of this chapter requiring a State plan or specifying the required contents of a State plan. This section is not intended to limit or expand the grounds for determining the availability of private actions to enforce State plan requirements other than by overturning any such grounds applied in Suter v. Artist M., 112 S. Ct. 1360 (1992), but not applied in prior Supreme Court decisions respecting such enforceability; provided, however, that this section is not intended to alter the holding in Suter v. Artist M. that section 671(a)(15) of this title is not enforceable in a private right of action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1320a-2?type=usc&year=mostrecent&link-type=html"},"by":{"1":"14","2":"11, 22","3":"13"},"q":[{"src":"brief","b":3,"text":"inclusion in a section of [the Act] requiring a State plan or specifying the required contents of a State plan.","cite":"42 U.S.C. §§ 1320a-2"}]},{"t":"law","label":"Pub. L. No. 100-203","url":"https://www.govinfo.gov/link/statute/101/1330","by":{"1":"3","2":"11"}},{"t":"usc","label":"31 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/31/6901","by":{"1":"17"}},{"t":"usc","label":"42 U.S.C. § 10801","url":"https://www.law.cornell.edu/uscode/text/42/10801","by":{"1":"34"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"1":"1","2":"1"}},{"t":"usc","label":"42 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/42/601","by":{"1":"12","2":"10, 11"}},{"t":"usc","label":"42 U.S.C. § 671","url":"https://www.law.cornell.edu/uscode/text/42/671","subs":["(a)(15)(1988)","(a)","(a)(15)"],"stext":{"head":"§671. State plan for foster care and adoption assistance","paras":[[0,"(a) Requisite features of State plan"],[0,"In order for a State to be eligible for payments under this part, it shall have a plan approved by the Secretary which—"],[1,"(1) provides for foster care maintenance payments in accordance with section 672 of this title, adoption assistance in accordance with section 673 of this title, and, at the option of the State, services or programs specified in subsection (e)(1) of this section for children who are candidates for foster care or who are pregnant or parenting foster youth and the parents or kin caregivers of the children, in accordance with the requirements of that subsection;"],[1,"(2) provides that the State agency responsible for administering the program authorized by subpart 1 of part B of this subchapter shall administer, or supervise the administration of, the program authorized by this part;"],[1,"(3) provides that the plan shall be in effect in all political subdivisions of the State, and, if administered by them, be mandatory upon them;"],[1,"(4) provides that the State shall assure that the programs at the local level assisted under this part will be coordinated with the programs at the State or local level assisted under parts A and B of this subchapter, under division A 1 of subchapter XX of this chapter, and under any other appropriate provision of Federal law;"],[1,"(5) provides that the State will, in the administration of its programs under this part, use such methods relating to the establishment and maintenance of personnel standards on a merit basis as are found by the Secretary to be necessary for the proper and efficient operation of the programs, except that the Secretary shall exercise no authority with respect to the selection, tenure of office, or compensation of any individual employed in accordance with such methods;"],[1,"(6) provides that the State agency referred to in paragraph (2) (hereinafter in this part referred to as the \"State agency\") will make such reports, in such form and containing such information as the Secretary may from time to time require, and comply with such provisions as the Secretary may from time to time find necessary to assure the correctness and verification of such reports;"],[1,"(7) provides that the State agency will monitor and conduct periodic evaluations of activities carried out under this part;"],[1,"(8) subject to subsection (c), provides safeguards which restrict the use of or disclosure of information concerning individuals assisted under the State plan to purposes directly connected with (A) the administration of the plan of the State approved under this part, the plan or program of the State under part A, B, or D of this subchapter or under subchapter I, V, X, XIV, XVI (as in effect in Puerto Rico, Guam, and the Virgin Islands), XIX, or XX, the program established by subchapter II, or the supplemental security income program established by subchapter XVI, (B) any investigation, prosecution, or criminal or civil proceeding, conducted in connection with the administration of any such plan or program, (C) the administration of any other Federal or federally assisted program which provides assistance, in cash or in kind, or services, directly to individuals on the basis of need, (D) any audit or similar activity conducted in connection with the administration of any such plan or program by any governmental agency which is authorized by law to conduct such audit or activity, and (E) reporting and providing information pursuant to paragraph (9) to appropriate authorities with respect to known or suspected child abuse or neglect; and the safeguards so provided shall prohibit disclosure, to any committee or legislative body (other than an agency referred to in clause (D) with respect to an activity referred to in such clause), of any information which identifies by name or address any such applicant or recipient; except that nothing contained herein shall preclude a State from providing standards which restrict disclosures to purposes more limited than those specified herein, or which, in the case of adoptions, prevent disclosure entirely;"],[1,"(9) provides that the State agency will—"],[2,"(A) report to an appropriate agency or official, known or suspected instances of physical or mental injury, sexual abuse or exploitation, or negligent treatment or maltreatment of a child receiving aid under part B or this part under circumstances which indicate that the child's health or welfare is threatened thereby;"],[2,"(B) provide such information with respect to a situation described in subparagraph (A) as the State agency may have; and"],[2,"(C) not later than—"],[3,"(i) 1 year after September 29, 2014, demonstrate to the Secretary that the State agency has developed, in consultation with State and local law enforcement, juvenile justice systems, health care providers, education agencies, and organizations with experience in dealing with at-risk children and youth, policies and procedures (including relevant training for caseworkers) for identifying, documenting in agency records, and determining appropriate services with respect to—"],[4,"(I) any child or youth over whom the State agency has responsibility for placement, care, or supervision and who the State has reasonable cause to believe is, or is at risk of being, a sex trafficking victim (including children for whom a State child welfare agency has an open case file but who have not been removed from the home, children who have run away from foster care and who have not attained 18 years of age or such older age as the State has elected under section 675(8) of this title, and youth who are not in foster care but are receiving services under section 677 of this title); and"],[4,"(II) at the option of the State, any individual who has not attained 26 years of age, without regard to whether the individual is or was in foster care under the responsibility of the State; and"],[3,"(ii) 2 years after September 29, 2014, demonstrate to the Secretary that the State agency is implementing the policies and procedures referred to in clause (i)."],[1,"(10) provides—"],[2,"(A) for the establishment or designation of a State authority or authorities that shall be responsible for establishing and maintaining standards for foster family homes and child care institutions which are reasonably in accord with recommended standards of national organizations concerned with standards for the institutions or homes, including standards related to admission policies, safety, sanitation, and protection of civil rights, and which shall permit use of the reasonable and prudent parenting standard;"],[2,"(B) that the standards established pursuant to subparagraph (A) shall be applied by the State to any foster family home or child care institution receiving funds under this part or part B and shall require, as a condition of each contract entered into by a child care institution to provide foster care, the presence on-site of at least 1 official who, with respect to any child placed at the child care institution, is designated to be the caregiver who is authorized to apply the reasonable and prudent parent standard to decisions involving the participation of the child in age or developmentally-appropriate activities, and who is provided with training in how to use and apply the reasonable and prudent parent standard in the same manner as prospective foster parents are provided the training pursuant to paragraph (24);"],[2,"(C) that the standards established pursuant to subparagraph (A) shall include policies related to the liability of foster parents and private entities under contract by the State involving the application of the reasonable and prudent parent standard, to ensure appropriate liability for caregivers when a child participates in an approved activity and the caregiver approving the activity acts in accordance with the reasonable and prudent parent standard; and"],[2,"(D) that a waiver of any standards established pursuant to subparagraph (A) may be made only on a case-by-case basis for nonsafety standards (as determined by the State) in relative foster family homes for specific children in care;"],[1,"(11) provides for periodic review of the standards referred to in the preceding paragraph and amounts paid as foster care maintenance payments and adoption assistance to assure their continuing appropriateness;"],[1,"(12) provides for granting an opportunity for a fair hearing before the State agency to any individual whose claim for benefits available pursuant to this part is denied or is not acted upon with reasonable promptness;"],[1,"(13) provides that the State shall arrange for a periodic and independently conducted audit of the programs assisted under this part and part B of this subchapter, which shall be conducted no less frequently than once every three years;"],[1,"(14) provides (A) specific goals (which shall be established by State law on or before October 1, 1982) for each fiscal year (commencing with the fiscal year which begins on October 1, 1983) as to the maximum number of children (in absolute numbers or as a percentage of all children in foster care with respect to whom assistance under the plan is provided during such year) who, at any time during such year, will remain in foster care after having been in such care for a period in excess of twenty-four months, and (B) a description of the steps which will be taken by the State to achieve such goals;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/671?type=usc&year=mostrecent&link-type=html"},"by":{"1":"12","2":"10, 11","3":"13"},"q":[{"src":"brief","b":1,"text":"to make it possible for the child to return to his home.","cite":"42 U.S.C. 671(a)(15)"},{"src":"brief","b":3,"text":"reasonable efforts shall be made to preserve and reunify families","cite":"42 U.S.C. § 671(a)(15)"}]},{"t":"usc","label":"42 U.S.C. § 1395","url":"https://www.law.cornell.edu/uscode/text/42/1395","by":{"1":"1","2":"13"}},{"t":"usc","label":"42 U.S.C. § 1395i-3","url":"https://www.law.cornell.edu/uscode/text/42/1395i-3","subs":["(c)","(c)(1)(A)","(c)(1)(A)(ii)","(c)(1)(A)(ii)(I)","(c)(1)(A)(vi)","(c)(2)","(c)(2)(A)","(c)(2)(A)(i)","(e)(3)","(g)(1)(A)","(g)(2)","(g)(2)(A)(ii)(III)","(g)(2)(B)","(g)(3)","(g)(4)","(g)(5)","(h)","(h)(2)(B)(ii)(IV)(ff)","(h)(5)"],"stext":{"head":"§1395i–3. Requirements for, and assuring quality of care in, skilled nursing facilities","paras":[[0,"(a) \"Skilled nursing facility\" defined"],[0,"In this subchapter, the term \"skilled nursing facility\" means an institution (or a distinct part of an institution) which—"],[1,"(1) is primarily engaged in providing to residents—"],[2,"(A) skilled nursing care and related services for residents who require medical or nursing care, or"],[2,"(B) rehabilitation services for the rehabilitation of injured, disabled, or sick persons,"],[1,"and is not primarily for the care and treatment of mental diseases;"],[1,"(2) has in effect a transfer agreement (meeting the requirements of section 1395x(l) of this title) with one or more hospitals having agreements in effect under section 1395cc of this title; and"],[1,"(3) meets the requirements for a skilled nursing facility described in subsections (b), (c), and (d) of this section."],[0,"(b) Requirements relating to provision of services"],[0,"(1) Quality of life"],[0,"(A) In general"],[2,"A skilled nursing facility must care for its residents in such a manner and in such an environment as will promote maintenance or enhancement of the quality of life of each resident."],[0,"(B) Quality assessment and assurance"],[2,"A skilled nursing facility must maintain a quality assessment and assurance committee, consisting of the director of nursing services, a physician designated by the facility, and at least 3 other members of the facility's staff, which (i) meets at least quarterly to identify issues with respect to which quality assessment and assurance activities are necessary and (ii) develops and implements appropriate plans of action to correct identified quality deficiencies. A State or the Secretary may not require disclosure of the records of such committee except insofar as such disclosure is related to the compliance of such committee with the requirements of this subparagraph."],[0,"(2) Scope of services and activities under plan of care"],[1,"A skilled nursing facility must provide services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident, in accordance with a written plan of care which—"],[2,"(A) describes the medical, nursing, and psychosocial needs of the resident and how such needs will be met;"],[2,"(B) is initially prepared, with the participation to the extent practicable of the resident or the resident's family or legal representative, by a team which includes the resident's attending physician and a registered professional nurse with responsibility for the resident; and"],[2,"(C) is periodically reviewed and revised by such team after each assessment under paragraph (3)."],[0,"(3) Residents' assessment"],[0,"(A) Requirement"],[2,"A skilled nursing facility must conduct a comprehensive, accurate, standardized, reproducible assessment of each resident's functional capacity, which assessment—"],[3,"(i) describes the resident's capability to perform daily life functions and significant impairments in functional capacity;"],[3,"(ii) is based on a uniform minimum data set specified by the Secretary under subsection (f)(6)(A);"],[3,"(iii) uses an instrument which is specified by the State under subsection (e)(5); and"],[3,"(iv) includes the identification of medical problems."],[0,"(B) Certification"],[0,"(i) In general"],[3,"Each such assessment must be conducted or coordinated (with the appropriate participation of health professionals) by a registered professional nurse who signs and certifies the completion of the assessment. Each individual who completes a portion of such an assessment shall sign and certify as to the accuracy of that portion of the assessment."],[0,"(ii) Penalty for falsification"],[3,"(I) An individual who willfully and knowingly certifies under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $1,000 with respect to each assessment."],[3,"(II) An individual who willfully and knowingly causes another individual to certify under clause (i) a material and false statement in a resident assessment is subject to a civil money penalty of not more than $5,000 with respect to each assessment."],[3,"(III) The provisions of section 1320a–7a of this title (other than subsections (a) and (b)) shall apply to a civil money penalty under this clause in the same manner as such provisions apply to a penalty or proceeding under section 1320a–7a(a) of this title."],[0,"(iii) Use of independent assessors"],[3,"If a State determines, under a survey under subsection (g) or otherwise, that there has been a knowing and willful certification of false assessments under this paragraph, the State may require (for a period specified by the State) that resident assessments under this paragraph be conducted and certified by individuals who are independent of the facility and who are approved by the State."],[0,"(C) Frequency"],[0,"(i) In general"],[3,"Subject to the timeframes prescribed by the Secretary under section 1395yy(e)(6) of this title, such an assessment must be conducted—"],[4,"(I) promptly upon (but no later than 14 days after the date of) admission for each individual admitted on or after October 1, 1990, and by not later than January 1, 1991, for each resident of the facility on that date;"],[4,"(II) promptly after a significant change in the resident's physical or mental condition; and"],[4,"(III) in no case less often than once every 12 months."],[0,"(ii) Resident review"],[3,"The skilled nursing facility must examine each resident no less frequently than once every 3 months and, as appropriate, revise the resident's assessment to assure the continuing accuracy of the assessment."],[0,"(D) Use"],[2,"The results of such an assessment shall be used in developing, reviewing, and revising the resident's plan of care under paragraph (2)."],[0,"(E) Coordination"],[2,"Such assessments shall be coordinated with any State-required preadmission screening program to the maximum extent practicable in order to avoid duplicative testing and effort."],[0,"(4) Provision of services and activities"],[0,"(A) In general"],[2,"To the extent needed to fulfill all plans of care described in paragraph (2), a skilled nursing facility must provide, directly or under arrangements (or, with respect to dental services, under agreements) with others for the provision of—"],[3,"(i) nursing services and specialized rehabilitative services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(ii) medically-related social services to attain or maintain the highest practicable physical, mental, and psychosocial well-being of each resident;"],[3,"(iii) pharmaceutical services (including procedures that assure the accurate acquiring, receiving, dispensing, and administering of all drugs and biologicals) to meet the needs of each resident;"],[3,"(iv) dietary services that assure that the meals meet the daily nutritional and special dietary needs of each resident;"],[3,"(v) an on-going program, directed by a qualified professional, of activities designed to meet the interests and the physical, mental, and psychosocial well-being of each resident;"],[3,"(vi) routine and emergency dental services to meet the needs of each resident; and"],[3,"(vii) treatment and services required by mentally ill and mentally retarded residents not otherwise provided or arranged for (or required to be provided or arranged for) by the State."],[2,"The services provided or arranged by the facility must meet professional standards of quality. Nothing in clause (vi) shall be construed as requiring a facility to provide or arrange for dental services described in that clause without additional charge."],[0,"(B) Qualified persons providing services"],[2,"Services described in clauses (i), (ii), (iii), (iv), and (vi) of subparagraph (A) must be provided by qualified persons in accordance with each resident's written plan of care."],[0,"(C) Required nursing care"],[0,"(i) In general"],[3,"Except as provided in clause (ii), a skilled nursing facility must provide 24-hour licensed nursing service which is sufficient to meet nursing needs of its residents and must use the services of a registered professional nurse at least 8 consecutive hours a day, 7 days a week."],[0,"(ii) Exception"],[3,"To the extent that clause (i) may be deemed to require that a skilled nursing facility engage the services of a registered professional nurse for more than 40 hours a week, the Secretary is authorized to waive such requirement if the Secretary finds that—"],[4,"(I) the facility is located in a rural area and the supply of skilled nursing facility services in such area is not sufficient to meet the needs of individuals residing therein,"],[4,"(II) the facility has one full-time registered professional nurse who is regularly on duty at such facility 40 hours a week,"],[4,"(III) the facility either has only patients whose physicians have indicated (through physicians' orders or admission notes) that each such patient does not require the services of a registered nurse or a physician for a 48-hour period, or has made arrangements for a registered professional nurse or a physician to spend such time at such facility as may be indicated as necessary by the physician to provide necessary skilled nursing services on days when the regular full-time registered professional nurse is not on duty,"],[4,"(IV) the Secretary provides notice of the waiver to the State long-term care ombudsman (established under section 307(a)(12) 1 of the Older Americans Act of 1965) and the protection and advocacy system in the State for the mentally ill and the mentally retarded, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395i-3?type=usc&year=mostrecent&link-type=html"},"by":{"1":"3, 3, 25, 26, 3, 3, 25, 26, 27, 3, 30, 25, 3, 26, 27, 4, 4, 32, 4, 4, 4, 4, 4, 4, 5, 31, 33, 34","2":"13"},"q":[{"src":"brief","b":1,"text":"must protect and promote the rights of each resident.","cite":"42 U.S.C. 1395i-3(c)(1)(A), 1396"},{"src":"brief","b":1,"text":"[t]he right to be free from physical or mental abuse, corporal punishment, involuntary seclusion, and any physical or chemical restraints imposed for purposes of discipline or convenience and not required to treat the resident’s medical symptoms.","cite":"42 U.S.C. 1395i-3(c)(1)(A)(ii), 1396"}]},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","by":{"1":"2","2":"13, 33"}},{"t":"usc","label":"42 U.S.C. § 1396c","url":"https://www.law.cornell.edu/uscode/text/42/1396c","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1396d","url":"https://www.law.cornell.edu/uscode/text/42/1396d","subs":["(a)"],"by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1320a-10","url":"https://www.law.cornell.edu/uscode/text/42/1320a-10","stext":{"head":"§1320a–10. Effect of failure to carry out State plan","paras":[[0,"In an action brought to enforce a provision of this chapter, such provision is not to be deemed unenforceable because of its inclusion in a section of this chapter requiring a State plan or specifying the required contents of a State plan. This section is not intended to limit or expand the grounds for determining the availability of private actions to enforce State plan requirements other than by overturning any such grounds applied in Suter v. Artist M., 112 S. Ct. 1360 (1992), but not applied in prior Supreme Court decisions respecting such enforceability: Provided, however, That this section is not intended to alter the holding in Suter v. Artist M. that section 671(a)(15) of this title is not enforceable in a private right of action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1320a-10?type=usc&year=mostrecent&link-type=html"},"by":{"1":"14","2":"11, 22","3":"13"}},{"t":"reg","label":"86 Fed. Reg. 42,424","url":"https://www.govinfo.gov/link/fr/86/42424","by":{"1":"2, 30"}},{"t":"case","label":"Ariz. State Legislature v. Ariz. Indep. Redistricting Comm’n","cite":"576 U.S. 787","y":2015,"id":"2014/13-1314","sc":1,"by":{"2":"21"}},{"t":"case","label":"Becerra v. Empire Health Found.","cite":"142 S. Ct. 2354","y":2022,"id":"2021/20-1312","sc":1,"by":{"2":"43"},"q":[{"src":"brief","b":2,"text":"is resolved by the most fundamental principle of statutory interpretation: Read the statute.","cite":"142 S. Ct. 2354, 236869"}]},{"t":"case","label":"Biden v. Texas","cite":"142 S. Ct. 2528","y":2022,"id":"2021/21-954","sc":1,"by":{"2":"22"}},{"t":"case","label":"Bomar v. Keyes","cite":"162 F.2d 136","y":1947,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/162/136/","by":{"2":"5"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"by":{"2":"21"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"by":{"2":"24"}},{"t":"case","label":"Burns v. Alcala","cite":"420 U.S. 575","y":1975,"id":"1974/73-1708","sc":1,"by":{"2":"6"}},{"t":"case","label":"Cal. Dep’t of Hum. Res. Dev. v. Java","cite":"402 U.S. 121","y":1971,"id":"1970/507","sc":1,"by":{"2":"5, 23"}},{"t":"case","label":"Carleson v. Remillard","cite":"406 U.S. 598","y":1972,"id":"1971/70-250","sc":1,"by":{"2":"6, 23"}},{"t":"case","label":"Cort v. Ash","cite":"422 U.S. 66","y":1975,"id":"1974/73-1908","sc":1,"by":{"2":"3"}},{"t":"case","label":"Crawford-El v. Britton","cite":"523 U.S. 574","y":1998,"id":"1997/96-827","sc":1,"by":{"2":"40"}},{"t":"case","label":"Cree v. Washington","cite":"990 F.2d 1256","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/990/1256/","by":{"2":"30"}},{"t":"case","label":"Cree v. Waterbury","cite":"78 F.3d 1400","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/78/1400/","by":{"2":"30"}},{"t":"case","label":"Dandridge v. Williams","cite":"397 U.S. 471","y":1970,"id":"1969/131","sc":1,"by":{"2":"5"}},{"t":"case","label":"Davis v. County of Westmoreland","cite":"844 A.2d 54","y":2004,"court":"Pa. Commw. Ct.","url":"https://www.courtlistener.com/c/A.2d/844/54/","by":{"2":"42"}},{"t":"case","label":"District of Columbia v. Carter","cite":"409 U.S. 418","y":1973,"id":"1972/71-564","sc":1,"by":{"2":"6"}},{"t":"case","label":"DuBerry v. District of Columbia","cite":"824 F.3d 1046","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/824/1046/","by":{"2":"3, 31"}},{"t":"case","label":"Edye v. Robertson","cite":"112 U.S. 580","y":1884,"id":"scdb/1884-060","sc":1,"by":{"2":"31","3":"10, 11"},"q":[{"src":"brief","b":3,"text":"[t]he best analogy when the federal government exchanges promises with a state under the Spending Clause is to a contract between sovereigns (a treaty).","cite":"112 U.S. 580, 586"}]},{"t":"case","label":"FCC v. NextWave Pers. Commc’ns Inc.","cite":"537 U.S. 293","y":2003,"id":"2002/01-653","sc":1,"by":{"2":"38"}},{"t":"case","label":"First Nat. Bank of Omaha v. Marquette Nat. Bank of Minneapolis","cite":"636 F.2d 195","y":1980,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/636/195/","by":{"2":"36"},"q":[{"src":"brief","b":2,"text":"from which § 1983 claims are to be made.","cite":"636 F.2d 195, 198"},{"src":"argument","who":"Mr. Robbins","text":"First, FNHRA and its implementing regulations provide a comprehensive suite of remedies, including a more restrictive private remedy that forecloses Section 1983 relief under Rancho Palos Verdes."},{"src":"argument","who":"Mr. Fisher","text":"First, they frustrate informed state assessment of Spending Clause programs. Second, they disrupt state efforts to administer complex spending programs using scarce resources."},{"src":"argument","who":"Mr. Snyder","text":"First, they offer no evidence that the Congress that enacted Section 1983 would have viewed breach-of-contract suits by third parties as remotely relevant to the new tort it was creating."}]},{"t":"case","label":"Golden State Transit Corp. v. City of Los Angeles","cite":"493 U.S. 103","y":1989,"id":"1989/88-840","sc":1,"by":{"2":"40","3":"13, 14"}},{"t":"case","label":"Hague v. Comm. Indus. Org.","cite":"307 U.S. 496","y":1939,"id":"1900-1940/307us496","sc":1,"by":{"2":"20"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"573 U.S. 258","y":2014,"id":"2013/13-317","sc":1,"by":{"2":"25"},"q":[{"src":"brief","b":2,"text":"argument that the precedent was wrongly decided.","cite":"573 U.S. 258, 266"}]},{"t":"case","label":"Hudson v. Michigan","cite":"547 U.S. 586","y":2006,"id":"2005/04-1360","sc":1,"by":{"2":"40"}},{"t":"case","label":"J.E.M. Ag Supply, Inc. v. Pioneer Hi-Bred Int’l, Inc.","cite":"534 U.S. 124","y":2001,"id":"2001/99-1996","sc":1,"by":{"2":"38"}},{"t":"case","label":"Jefferson v. Hackney","cite":"406 U.S. 535","y":1972,"id":"1971/70-5064","sc":1,"by":{"2":"6"}},{"t":"case","label":"Jett v. Dallas Indep. Sch. Dist.","cite":"491 U.S. 701","y":1989,"id":"1988/87-2084","sc":1,"by":{"2":"5"}},{"t":"case","label":"Knick v. Twp. of Scott","cite":"139 S. Ct. 2162","y":2019,"id":"2018/17-647","sc":1,"by":{"2":"4"}},{"t":"case","label":"Lewis v. Martin","cite":"397 U.S. 552","y":1970,"id":"1969/829","sc":1,"by":{"2":"5"}},{"t":"case","label":"McGrath v. Kristensen","cite":"340 U.S. 162","y":1950,"id":"1940-1955/340us162","sc":1,"by":{"2":"28"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"by":{"2":"25, 26"}},{"t":"case","label":"Mitchum v. Foster","cite":"407 U.S. 225","y":1972,"id":"1971/70-27","sc":1,"by":{"2":"4, 5, 40"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"`Sheriffs, having eyes to see, see not; judges, having ears to hear, hear not; witnesses conceal the truth or falsify it; grand and petit juries act as if they might be accomplices. . . . [A]ll the apparatus and machinery of civil government, all the processes of justice, skulk away as if government and justice were crimes and feared detection. Among the most dangerous things an injured party can do is to appeal to justice.'","cite":"407 U. S., at 241"}]},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"by":{"2":"38"},"q":[{"src":"brief","b":2,"text":"repeals by implication are not favored.","cite":"417 U.S. 535, 549"}]},{"t":"case","label":"N.Y. Dep’t of Soc. Servs. v. Dublino","cite":"413 U.S. 405","y":1973,"id":"1972/72-792","sc":1,"by":{"2":"6"}},{"t":"case","label":"Neal v. United States","cite":"516 U.S. 284","y":1996,"id":"1995/94-9088","sc":1,"by":{"2":"25"}},{"t":"case","label":"Ohio Bureau of Emp. Servs. v. Hodory","cite":"431 U.S. 471","y":1977,"id":"1976/75-1707","sc":1,"by":{"2":"6"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"142 S. Ct. 2486","y":2022,"id":"2021/21-429","sc":1,"by":{"2":"27, 28"},"q":[{"src":"brief","b":2,"text":"And this Court does not rewrite a constitutionally valid statutory text under the banner of speculation about what Congress might have done had it faced a question that ... it never faced.","cite":"142 S. Ct. at 2497"}]},{"t":"case","label":"Oklahoma City v. Tuttle","cite":"471 U.S. 808","y":1985,"id":"1984/83-1919","sc":1,"by":{"2":"25"}},{"t":"case","label":"Patsy v. Bd. of Regents","cite":"457 U.S. 496","y":1982,"id":"1981/80-1874","sc":1,"by":{"2":"6, 25"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"by":{"2":"25"}},{"t":"case","label":"Philbrook v. Glodgett","cite":"421 U.S. 707","y":1975,"id":"1974/73-1820","sc":1,"by":{"2":"6, 23"}},{"t":"case","label":"Pulliam v. Allen","cite":"466 U.S. 522","y":1984,"id":"1983/82-1432","sc":1,"by":{"2":"11"}},{"t":"case","label":"Quarles v. United States","cite":"139 S. Ct. 1872","y":2019,"id":"2018/17-778","sc":1,"by":{"2":"22, 23"}},{"t":"case","label":"Ramos v. Louisiana","cite":"140 S. Ct. 1390","y":2020,"id":"2019/18-5924","sc":1,"by":{"2":"25"}},{"t":"case","label":"Romero v. Kitsap Cnty.","cite":"931 F.2d 624","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/931/624/","by":{"2":"30"}},{"t":"case","label":"Rosado v. Wyman","cite":"397 U.S. 397","y":1970,"id":"1969/540","sc":1,"by":{"2":"5, 6, 22, 23"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"by":{"2":"24"}},{"t":"case","label":"Shea v. Vialpando","cite":"416 U.S. 251","y":1974,"id":"1973/72-1513","sc":1,"by":{"2":"6, 23"}},{"t":"case","label":"Texas v. Johnson","cite":"491 U.S. 397","y":1989,"id":"1988/88-155","sc":1,"by":{"2":"45"}},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affs. v. Inclusive Communities Project, Inc.","cite":"576 U.S. 519","y":2015,"id":"2014/13-1371","sc":1,"by":{"2":"22, 23, 25"}},{"t":"case","label":"TVA v. Hill","cite":"437 U.S. 153","y":1978,"id":"1977/76-1701","sc":1,"by":{"2":"8"}},{"t":"case","label":"U.S. Nat’l Bank of Or. v. Indep. Ins. Agents of Am., Inc.","cite":"508 U.S. 439","y":1993,"id":"1992/92-484","sc":1,"by":{"2":"4"}},{"t":"case","label":"UARG v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"by":{"2":"42"}},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2022,"id":"2021/20-1530","sc":1,"by":{"2":"42"}},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"by":{"2":"31"},"q":[{"src":"brief","b":2,"text":"Of course, there will be some hard cases.","cite":"142 S. Ct. 1063, 1071"}]},{"t":"case","label":"Yellen v. Confederated Tribes of Chehalis Rsrv.","cite":"141 S. Ct. 2434","y":2021,"id":"2020/20-543","sc":1,"by":{"2":"27"}},{"t":"usc","label":"18 U.S.C. § 926C","url":"https://www.law.cornell.edu/uscode/text/18/926C","by":{"2":"3, 31"}},{"t":"usc","label":"20 U.S.C. § 1232g","url":"https://www.law.cornell.edu/uscode/text/20/1232g","subs":["(f)"],"by":{"2":"12, 13"}},{"t":"usc","label":"42 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/42/1301","by":{"2":"11, 22"}},{"t":"usc","label":"42 U.S.C. § 1437a","url":"https://www.law.cornell.edu/uscode/text/42/1437a","by":{"2":"10"}},{"t":"usc","label":"42 U.S.C. § 1997a","url":"https://www.law.cornell.edu/uscode/text/42/1997a","subs":["(a)"],"by":{"2":"7, 8, 7","3":"14"}},{"t":"usc","label":"42 U.S.C. § 6010","url":"https://www.law.cornell.edu/uscode/text/42/6010","by":{"2":"9, 10"},"q":[{"src":"argument","who":"Mr. Robbins","text":"It did in Pennhurst itself with a long section of bill -- called Bill of Rights in Section 6010 of the Rehab Act of '73. That wasn't enough."}]},{"t":"law","label":"Federal Courts Improvement Act, Pub. L. No. 104-317","url":"https://www.govinfo.gov/link/plaw/104/public/317","by":{"2":"11"}},{"t":"law","label":"Pub. L. No. 96-170","url":"https://www.govinfo.gov/link/statute/93/1284","by":{"2":"6"}},{"t":"reg","label":"42 C.F.R. § 431.231","url":"https://www.ecfr.gov/current/title-42/section-431.231","by":{"2":"40"}},{"t":"reg","label":"42 C.F.R. § 483.12","url":"https://www.ecfr.gov/current/title-42/section-483.12","subs":["(c)"],"by":{"2":"40"}},{"t":"reg","label":"39 Fed. Reg. 15230","url":"https://www.govinfo.gov/link/fr/39/15230","by":{"2":"15"}},{"t":"reg","label":"39 Fed. Reg. 35774","url":"https://www.govinfo.gov/link/fr/39/35774","by":{"2":"15"}},{"t":"reg","label":"46 Fed. Reg. 7408","url":"https://www.govinfo.gov/link/fr/46/7408","by":{"2":"15"}},{"t":"case","label":"Allen v. Thomas","cite":"60 Ky. 198","y":1860,"url":"https://www.courtlistener.com/c/Ky./60/198/","by":{"3":"7"}},{"t":"case","label":"Arlington Cent. Sch. Dist. Bd. of Educ. v. Murphy","cite":"548 U.S. 291","y":2006,"id":"2005/05-18","sc":1,"by":{"3":"2"},"q":[{"src":"brief","b":3,"text":"a state official … deciding whether the State should accept funds and the obligations that go with those funds.","cite":"548 U.S. 291, 296"},{"src":"argument","who":"Mr. Robbins","text":"Chief Justice, and may it please the Court: The key to Spending Clause statutes, this Court said in Arlington Central School District, \"is what the states are clearly told regarding the conditions that go along with the acceptance of federal funds.\" Among the most costly conditions that may go along with the acceptance of federal funds is exposure to private litigation under Section 1983."}]},{"t":"case","label":"Astra USA, Inc. v. Santa Clara Cnty.","cite":"563 U.S. 110","y":2011,"id":"2010/09-1273","sc":1,"by":{"3":"10"}},{"t":"case","label":"Barnes v. Gorman","cite":"536 U.S. 181","y":2002,"id":"2001/01-682","sc":1,"by":{"3":"12"},"q":[{"src":"argument","who":"Mr. Robbins","text":"This Court made that precise point in Barnes against Gorman, in which it said with respect to a school that \"without doubt, the scope of potential damages liability is one of the most significant factors a school\" -- or, as in this case, a nursing facility -- \"would consider in deciding whether to receive federal funds.\" States are therefore entitled, in our view, to clear notice that they will be subject to such private lawsuits if they expect -- if they accept Spending Clause money."}]},{"t":"case","label":"Bohanan v. Pope","cite":"42 Me. 93","y":1856,"url":"https://www.courtlistener.com/c/Me./42/93/","by":{"3":"7"}},{"t":"case","label":"Brewer v. Dyer","cite":"61 Mass. 337","y":1851,"url":"https://www.courtlistener.com/c/Mass./61/337/","by":{"3":"7"}},{"t":"case","label":"Bristow v. Lane","cite":"21 Ill. 194","y":1859,"url":"https://www.courtlistener.com/c/Ill./21/194/","by":{"3":"7"}},{"t":"case","label":"Comm. of U.S. Citizens Living in Nicar. v. Reagan","cite":"859 F.2d 929","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/859/929/","by":{"3":"11"}},{"t":"case","label":"Foster v. Lookout Water Co.","cite":"71 Tenn. 42","y":1879,"url":"https://www.courtlistener.com/c/Tenn./71/42/","by":{"3":"9"}},{"t":"case","label":"Franklin v. Gwinnett Cnty. Pub. Schs.","cite":"503 U.S. 60","y":1992,"id":"1991/90-918","sc":1,"by":{"3":"14"},"q":[{"src":"brief","b":3,"text":"remedies (including remedies both at law and in equity) are available for such a violation to the same extent as such remedies are available for such a violation in the suit against any public or private entity other than a State.","cite":"503 U.S. 60, 72-73"}]},{"t":"case","label":"Frolova v. U.S.S.R.","cite":"761 F.2d 370","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/761/370/","by":{"3":"11"}},{"t":"case","label":"Haitian Refugee Ctr. v. Baker","cite":"949 F.2d 1109","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/949/1109/","by":{"3":"11"}},{"t":"case","label":"Hind v. Holdship","cite":"2 Watts 104","y":1833,"court":"Pa.","url":"https://www.courtlistener.com/c/Watts/2/104/","by":{"3":"7"}},{"t":"case","label":"Morgan v. Overman Silver Mining Co.","cite":"37 Cal. 534","y":1869,"url":"https://www.courtlistener.com/c/Cal./37/534/","by":{"3":"7"}},{"t":"case","label":"Nickerson v. Bridgeport Hydraulic Co.","cite":"46 Conn. 24","y":1878,"url":"https://www.courtlistener.com/c/Conn./46/24/","by":{"3":"9"}},{"t":"const","label":"Article I, Section 8","by":{"3":"2"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"3":"2"}},{"t":"usc","label":"42 U.S.C. § 2000d-7","url":"https://www.law.cornell.edu/uscode/text/42/2000d-7","subs":["(a)(2)"],"by":{"3":"14"}}]};